import { NextResponse } from "next/server";
import { createClient } from "@/utils/supabase/server";
import crypto from "crypto";

export async function POST(req: Request) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { amount, method } = await req.json();
    const numAmount = Number(amount);
    if (!amount || isNaN(numAmount) || numAmount <= 0) {
      return NextResponse.json({ error: "Invalid deposit amount" }, { status: 400 });
    }

    const refNo = `TXN-DEP-${crypto.randomBytes(4).toString("hex").toUpperCase()}`;

    // Insert manually into wallet_transactions to trigger deduction / addition trigger.
    const { data: txn, error } = await supabase
      .from("wallet_transactions")
      .insert({
        wallet_id: user.id,
        type_id: "manual_adjustment",
        status_id: "completed",
        amount: numAmount,
        reference_number: refNo,
        description: `Wallet Deposit via ${method.toUpperCase()}`,
      })
      .select("id")
      .single();

    if (error || !txn) {
      throw new Error(error?.message || "Failed to log deposit transaction.");
    }

    return NextResponse.json({ success: true, reference: refNo });
  } catch (err) {
    const msg = err instanceof Error ? err.message : "Unknown error";
    return NextResponse.json({ error: msg }, { status: 500 });
  }
}
